def transform(grid):
    h,w=len(grid),len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
    out=[row[:] for row in grid]
    # Replicate shape-rectangle lines through each marker: markers indicate missing extensions aligned across the rectangle.
    rs=[r for r in range(h) for c in range(w) if grid[r][c]==2]
    cs=[c for r in range(h) for c in range(w) if grid[r][c]==2]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    # For markers outside colored block, extend corresponding row or column across the grid, using 2 where ray crosses
    # The demo shows every nonzero marker produces full row if its row intersects block extent; and columns for markers below.
    for r,c in cells:
        if r<r0 or r>r1:
            for rr in range(r,h):
                if rr>=r0: break
            # vertical stripe extending through/out from block, aligned marker column
            for rr in range(h):
                if c0<=c<=c1: out[rr][c]=2
        else:
            for cc in range(w):
                if c0<=cc<=c1: out[r][cc]=2
    # Specifically lines through all marker positions: horizontal row/vertical col across solid rectangle; outside block portions remain
    for r,c in cells:
        if r0<=r<=r1:
            for cc in range(c0,c1+1): out[r][cc]=2
        if c0<=c<=c1:
            for rr in range(r0,r1+1): out[rr][c]=2
    return out
